@media (max-width: 639.98px) {
  [data-slot="dialog-footer"]:has(> button:nth-child(2):last-child):not(:has(> :not(button))),
  [data-slot="alert-dialog-footer"]:has(> button:nth-child(2):last-child):not(:has(> :not(button))) {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.5rem;
  }
  [data-slot="dialog-footer"]:has(> button:nth-child(2):last-child):not(:has(> :not(button))) > button,
  [data-slot="alert-dialog-footer"]:has(> button:nth-child(2):last-child):not(:has(> :not(button))) > button {
    width: 100%;
    margin: 0;
  }
}

[data-slot="calendar"] [data-today="true"] {
  background: transparent;
  border-radius: 0.375rem;
  box-shadow: inset 0 0 0 1px var(--muted-foreground);
  color: var(--foreground);
}
[data-slot="calendar"] [data-today="true"] > * {
  font-weight: 700;
}
